add('start-island','Lv. 1–9: 섬 퀘스트를 동선에 묶기',list(jobs),1,9,'처음부터 퀘스트와 처치 목표를 묶고 10레벨 전직을 준비합니다.',['받을 수 있는 섬 퀘스트의 처치·수집 목표를 한 번에 확인하고 겹치는 목표부터 진행합니다.','퀘스트 재료를 팔기 전에 필요한 수량과 다음 퀘스트 연결을 확인합니다.','돈이 부족하면 재료 전부를 보관하기보다 앞으로 쓸 수량만 남기고 보급 예산을 확보합니다.','10레벨이 되면 진로의 전직관을 찾습니다. Classic World의 마법사 전직도 현재 참조 자료는 10레벨이며 과거 메이플의 8레벨 정보와 구분합니다.'],'Getting started','시작','먼저 확인')
first={
'warrior':('명중과 근접 동선부터 안정화','Warrior',['페리온의 주먹펴고 일어서에게 1차 전직을 확인합니다.','파워 스트라이크의 처치 타수와 슬래시 블래스트로 실제 함께 맞히는 수를 별도로 측정합니다.','빗나감이 잦으면 공격력만 올리기 전에 명중 장비·레벨 차이를 확인합니다.','HP 회복력 향상 3 → 최대 HP 증가, 최대 HP 증가 3 → 아이언 바디의 선행을 확인합니다. Classic 스킬 수치와 과거 빌드를 섞지 않습니다.']),
'magician':('물약 예산과 공격 주문 선택','Magician',['엘리니아의 하인즈에게 1차 전직을 확인합니다.','에너지 볼트와 매직 클로를 각각 실제 처치 타수·MP 소모로 비교합니다.','매직 클로는 에너지 볼트 1, 최대 MP 증가는 MP 회복력 향상 3, 매직 아머는 매직 가드 3이 선행입니다.','매직 가드 사용 전후의 HP·MP 물약비와 사망 위험을 함께 측정합니다. 안정적인 사냥이 가능한 MP 예비비를 먼저 남깁니다.']),
'bowman':('사거리와 근접 대응을 함께 보기','Bowman',['헤네시스의 헬레나에게 1차 전직을 확인합니다.','더블 샷은 애로우 블로우 1, 포커스는 아마존의 눈 3 선행을 확인합니다.','처치가 빠르더라도 몬스터가 바로 붙는 지형에서 넉백·재정렬에 드는 시간을 기록합니다.','현재 Classic의 크리티컬 샷 상한은 참조 자료에서 15입니다. 과거의 상한 20 빌드를 그대로 적용하지 않습니다.']),
'thief':('표창·단검 진로와 보급 계획','Thief',['커닝시티의 다크로드에게 1차 전직을 확인합니다.','표창 진로라면 럭키 세븐과 아대, 단검 진로라면 더블 스탭의 실제 처치 속도를 기준으로 기록합니다.','킨 아이즈는 님블 바디 3, 다크 사이트는 디스오더 3 선행을 확인합니다.','왕복 재보급 시간을 사냥 기록에 포함합니다. 표창·MP·HP 비용이 서로 다른 무기 후보는 공격력만으로 비교하지 않습니다.'])}
for f,(title,page,steps) in first.items():add(f+'-first',f'Lv. 10–29 {jobs[f]}: '+title,family[f],10,29,'1차 전직 후의 첫 장비·스킬·보급 우선순위를 확인합니다.',steps,page,priority='전직 후 먼저')
second={
'fighter':('Warrior',['검과 도끼 중 지금 확보한 무기·시세·사냥 동작에 맞는 한 계열을 먼저 정합니다.','같은 계열 마스터리 3은 파이널 어택, 5는 부스터 선행입니다. 반대 무기 계열까지 동시에 투자하면 현재 주무기의 성장 SP가 줄어듭니다.','분노의 버프 효과와 포션 비용, 러시 사용으로 모이는 몬스터 수를 각각 측정합니다.','범위 공격으로 맞힌 수·접근 시간·혼잡도를 포함해 사냥 기록을 비교하고, 비싼 무기 교체 전에 실제 처치 타수 감소를 확인합니다.']),
'page':('Warrior',['검과 둔기 중 현재 주무기·가격·공격 동작에 맞는 계열을 선택합니다.','무기 마스터리 3 → 파이널 어택, 마스터리 5 → 부스터의 선행을 맞춥니다.','위협과 러시를 써서 줄어드는 피격·이동 시간을 실제 사냥으로 확인합니다.','장래 전직을 가정해 현재 효율을 확정하지 않습니다. 출시 버전의 2차 도구와 내 사냥 기록으로 다음 장비를 고릅니다.']),
'spearman':('Warrior',['창과 폴암을 같은 가격·강화 상태로 맞춰 실제 공격 동작과 처치 타수를 비교합니다.','각 무기 마스터리 3 → 해당 파이널 어택, 마스터리 5 → 해당 부스터의 선행을 따릅니다.','아이언 월을 사용한 파티와 솔로의 피격·물약비를 따로 기록합니다.','러시로 모으는 범위와 지형의 단차가 사냥 속도에 주는 영향을 확인합니다. 과거 하이브리드 빌드를 자동으로 최적이라고 취급하지 않습니다.']),
'firePoison':('Magician',['불 공격과 독 공격의 실제 피해·상태 이상 적용 여부를 몬스터별로 먼저 확인합니다.','지속 피해를 기다리는 동안 다른 몬스터를 처리하는 동선과 마무리 시간을 기록합니다.','MP 이터 3 → 메디테이션의 선행을 확인하고, 텔레포트의 이동 이득과 MP 비용을 함께 비교합니다.','빠른 첫 타격만 기록하지 말고 독으로 끝나는 시간까지 포함해 경험치·물약·전리품을 측정합니다.']),
'iceLightning':('Magician',['콜드 빔의 단일 대상 제어와 선더 볼트의 실제 명중 대상 수를 나눠 비교합니다.','범위 공격이 여러 층을 실제로 맞히는지, 얼음·번개가 통하지 않는 대상이 있는지 확인합니다.','MP 이터 3 → 메디테이션의 선행을 확인합니다. 텔레포트로 줄어드는 왕복 시간보다 MP 비용이 커지는지도 확인합니다.','피격을 줄여 물약비가 내려가는 효과와 처치 속도 개선을 사냥 기록에 따로 남깁니다.']),
'cleric':('Magician',['힐이 피해를 주는 언데드 여부를 도감과 게임에서 확인한 뒤 실제 맞히는 수를 측정합니다.','힐 5 → 인빈서블, 인빈서블 5 → 블레스 선행을 확인합니다.','파티원의 회복 수요와 파티 경험치 규칙을 확인하고 솔로·파티 기록을 분리합니다.','힐을 사용해도 MP 비용과 이동·대기 시간이 발생합니다. 물약 절약만으로 최고 효율이라고 단정하지 않습니다.']),
'hunter':('Bowman',['활 마스터리 3 → 파이널 어택, 마스터리 5 → 보우 부스터를 확인합니다.','애로우 봄의 범위에 실제 함께 맞는 몬스터 수와 가까이 붙었을 때의 대응 시간을 측정합니다.','소울 애로우 사용 전후의 화살·MP·왕복 보급 비용을 비교합니다.','아마존의 심판 등 현재 Classic 추가 스킬을 확인하고, 과거 소울 애로우·파이널 어택 빌드의 수치를 그대로 복사하지 않습니다.']),
'crossbowman':('Bowman',['석궁 마스터리 3 → 파이널 어택, 마스터리 5 → 크로스보우 부스터를 확인합니다.','아이언 애로우가 직선으로 여러 대상을 맞히기 좋은 지형과 몬스터 간격을 찾습니다.','긴 직선 맵이라도 걸어가는 시간·층 이동·경쟁을 포함하면 효율이 달라질 수 있어 전체 구간을 측정합니다.','활 매물과 석궁 매물은 호환되지 않습니다. 같은 주스탯이라도 사용할 수 있는 무기 계열을 먼저 필터링합니다.']),
'assassin':('Thief',['자벨린 마스터리 3 → 크리티컬 스로우, 5 → 자벨린 부스터의 선행을 맞춥니다.','크리티컬 리커버리 3 → 드레인의 선행과 실제 회복·물약 절감 효과를 확인합니다.','헤이스트를 써서 줄어드는 이동 시간과 파티원의 동선을 함께 기록합니다.','비싼 표창의 공격력 증가가 현재 몬스터 처치 타수를 줄이지 못하면, 무기·방어·물약 예산 후보와 비교한 뒤 구매합니다.']),
'bandit':('Thief',['대거 마스터리 5 → 대거 부스터, 헤이스트 5 → 스틸의 선행을 맞춥니다.','새비지 블로우와 스틸의 현재 Classic 피해·범위를 실제 대상에게 확인합니다.','적에게 붙는 시간·접촉 피해·넉백을 포함해 시간당 경험치와 물약비를 측정합니다.','단검의 공격력·LUK·착용 조건과 실제 공격 동작을 함께 비교합니다. 표도 장비와 단도 장비를 한 순위로 섞지 않습니다.'])}
